use sha2::{Digest, Sha256};
use std::{
    path::{Path, PathBuf},
    sync::OnceLock,
};

/// Frozen exporter facts, not values generated by the geometry under test.
pub fn fixture_record(rel_path: &str) -> &'static serde_json::Value {
    static ORIGINAL: OnceLock<serde_json::Value> = OnceLock::new();
    static OCCT: OnceLock<serde_json::Value> = OnceLock::new();
    let (cell, manifest, name) = if let Some(name) = rel_path.strip_prefix("independent-exporters/")
    {
        (&OCCT, "independent-exporters/manifest.json", name)
    } else {
        (&ORIGINAL, "manifest.json", rel_path)
    };
    let document = cell.get_or_init(|| {
        serde_json::from_slice(&std::fs::read(fixtures_dir().join(manifest)).unwrap()).unwrap()
    });
    document["fixtures"]
        .as_array()
        .unwrap()
        .iter()
        .find(|row| row["path"].as_str() == Some(name))
        .unwrap_or_else(|| panic!("fixture has no frozen manifest entry: {rel_path}"))
}

pub fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("tests directory must have parent")
        .join("fixtures")
        .join("geometry")
}

pub fn fixture_path(rel_path: &str) -> PathBuf {
    fixtures_dir().join(rel_path)
}

pub fn fixture_bytes(rel_path: &str) -> Vec<u8> {
    let p = fixture_path(rel_path);
    let bytes =
        std::fs::read(&p).unwrap_or_else(|e| panic!("failed to read fixture at {:?}: {e}", p));
    let record = fixture_record(rel_path);
    let size = record["byte_count"]
        .as_u64()
        .or_else(|| record["bytes"].as_u64())
        .unwrap();
    assert_eq!(bytes.len() as u64, size, "frozen fixture size: {rel_path}");
    assert_eq!(
        format!("{:x}", Sha256::digest(&bytes)),
        record["sha256"].as_str().unwrap(),
        "frozen fixture hash: {rel_path}"
    );
    bytes
}

pub fn fixture_str(rel_path: &str) -> String {
    String::from_utf8(fixture_bytes(rel_path)).expect("frozen STEP fixture is UTF-8")
}

